import * as React from "react"
import { AnimatePresence } from "motion/react"
import { FolderIcon, MessageCircleIcon } from "lucide-react"

import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import { Sparkline } from "@/components/ds/sparkline"
import { StageTrack, stageTrackGrid } from "@/components/ds/stage-track"
import { StatusBadge } from "@/components/ds/status"
import {
  Widget,
  WidgetHeader,
  WidgetList,
  WidgetListHeader,
  WidgetListRow,
  WidgetPanel,
  WidgetTitle,
} from "@/components/ds/widget"
import { DecisionChip } from "@/components/parts/decision-chip"
import { KIND_LABEL, STAGES, type Health } from "@/examples/bottega/data"
import { Conversation } from "@/examples/bottega/conversation"
import { useBottega } from "@/examples/bottega/use-bottega"

// Bottega: an autonomous software workshop, as a page. What needs the person
// comes first; projects show where they are in the flow (conversation →
// plan → execution → proof → publish → observe), not their tasks;
// production is shown as outcomes; the agent's own work is a quiet log. The
// one conversation sits on the right, and decisions are answered there.

const ALL = "all"
// Mobile: name · now on one line, the track full width below it.
// From md: name · track · now in three columns.
const PROJECT_COLS =
  "grid-cols-[minmax(0,1.2fr)_minmax(0,1fr)] gap-y-2.5 md:grid-cols-[minmax(8rem,1fr)_minmax(15rem,26rem)_minmax(6rem,11rem)]"
const LIVE_COLS = "grid-cols-[minmax(0,1fr)_4rem_6.5rem] sm:grid-cols-[minmax(7rem,1fr)_5rem_4rem_6.5rem]"

const HEALTH: Record<Health, { tone: "success" | "warning" | "info"; label: string }> = {
  ok: { tone: "success", label: "Saudável" },
  degraded: { tone: "warning", label: "Instável" },
  recovering: { tone: "info", label: "Recuperando" },
}

export function Bottega() {
  const state = useBottega()
  const { projects, decisions, activity } = state
  const [filter, setFilter] = React.useState(ALL)
  const [hovered, setHovered] = React.useState<string | null>(null)
  const [flash, setFlash] = React.useState<string | null>(null)
  // Below lg the conversation is a full-screen sheet instead of a rail.
  const [chatOpen, setChatOpen] = React.useState(false)

  const inScope = (pid: string) => filter === ALL || filter === pid
  const open = decisions.filter((d) => d.state === "open" && inScope(d.project))
  const live = projects.filter((p) => p.live && inScope(p.id))
  const name = (pid: string) => projects.find((p) => p.id === pid)?.name ?? pid

  function openDecision(id: string) {
    const wide = window.matchMedia("(min-width: 64rem)").matches
    if (!wide) setChatOpen(true)
    // Let the sheet mount before scrolling to the card.
    window.setTimeout(() => {
      document.getElementById(`decision-${id}`)?.scrollIntoView({ behavior: "smooth", block: "center" })
      setFlash(id)
      window.setTimeout(() => setFlash(null), 1400)
    }, wide ? 0 : 150)
  }

  return (
    <div data-slot="bottega" className="grid h-svh grid-cols-1 bg-background lg:grid-cols-[minmax(0,1fr)_26rem]">
      <main className="flex min-h-0 flex-col overflow-y-auto">
        {/* pr-16 leaves room for the playground's theme toggle */}
        <header className="sticky top-0 z-10 flex h-14 shrink-0 items-center gap-3 border-b border-border/70 bg-background/90 px-4 backdrop-blur sm:px-6">
          <span className="text-[15px]">Oficina</span>
          <span className="eyebrow text-muted-foreground max-sm:hidden">
            {projects.length} projetos · {projects.filter((p) => p.live).length} no ar
          </span>
          <Select value={filter} onValueChange={(v) => v && setFilter(v)}>
            <SelectTrigger aria-label="Projeto" className="ml-auto">
              <FolderIcon className="text-muted-foreground" />
              <SelectValue>{(v: string) => (v === ALL ? "Todos os projetos" : name(v))}</SelectValue>
            </SelectTrigger>
            <SelectContent align="end" alignItemWithTrigger={false}>
              <SelectItem value={ALL}>Todos os projetos</SelectItem>
              {projects.map((p) => (
                <SelectItem key={p.id} value={p.id}>
                  {p.name}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </header>

        <div className="mx-auto flex w-full max-w-[60rem] flex-col gap-8 px-4 pt-6 pb-28 sm:px-6 sm:pt-8 lg:pb-8">
          {/* What needs the person: the only orange on the page. */}
          <section className="flex flex-col gap-3">
            <div className="flex items-baseline gap-2 px-1">
              <h2 className="text-base">Precisa de você</h2>
              <span className="eyebrow text-muted-foreground">{open.length || "nada"}</span>
            </div>
            {open.length > 0 ? (
              <div className="grid grid-cols-1 gap-3 sm:grid-cols-3">
                <AnimatePresence mode="popLayout">
                  {open.map((d) => (
                    <DecisionChip key={d.id} kind={KIND_LABEL[d.kind]} subject={name(d.project)} onClick={() => openDecision(d.id)}>
                      {d.ask}
                    </DecisionChip>
                  ))}
                </AnimatePresence>
              </div>
            ) : (
              <p className="px-1 text-sm text-muted-foreground">Nada esperando você. A Bottega segue sozinha.</p>
            )}
          </section>

          <Widget>
            <WidgetHeader>
              <WidgetTitle>Projetos</WidgetTitle>
            </WidgetHeader>
            <WidgetPanel className="flex flex-col pt-3">
              <WidgetList onMouseLeave={() => setHovered(null)}>
                <WidgetListHeader className={PROJECT_COLS}>
                  <span className="eyebrow text-muted-foreground">Projeto</span>
                  <span className="grid max-md:hidden" style={stageTrackGrid(STAGES.length)}>
                    {STAGES.map((s) => (
                      <span key={s} className="truncate text-xs text-muted-foreground">
                        {s}
                      </span>
                    ))}
                  </span>
                  <span className="eyebrow text-right text-muted-foreground">Agora</span>
                </WidgetListHeader>
                {projects.map((p) => (
                  <WidgetListRow
                    key={p.id}
                    className={PROJECT_COLS}
                    selected={filter === p.id}
                    dimmed={(hovered !== null && hovered !== p.id) || !inScope(p.id)}
                    onMouseEnter={() => setHovered(p.id)}
                    onClick={() => setFilter((f) => (f === p.id ? ALL : p.id))}
                  >
                    <span className="flex min-w-0 flex-col gap-0.5">
                      <span className="truncate">{p.name}</span>
                      <span className="truncate text-xs text-muted-foreground">{p.goal}</span>
                    </span>
                    <StageTrack
                      className="col-span-2 order-last md:order-none md:col-span-1"
                      stages={p.stages.map((status, i) => ({ label: STAGES[i], status }))}
                      statusLabels={{ done: "concluída", active: "em andamento", waiting: "esperando você", failed: "falhou", todo: "a fazer" }}
                    />
                    <span
                      className={cn(
                        "truncate text-right text-xs",
                        p.stages.includes("waiting") || p.stages.includes("failed") ? "text-foreground" : "text-muted-foreground"
                      )}
                    >
                      {p.now}
                    </span>
                  </WidgetListRow>
                ))}
              </WidgetList>
            </WidgetPanel>
          </Widget>

          <div className="grid grid-cols-1 gap-8 xl:grid-cols-2">
            <Widget>
              <WidgetHeader>
                <WidgetTitle>Produção</WidgetTitle>
              </WidgetHeader>
              <WidgetPanel className="flex flex-col pt-3">
                <WidgetList>
                  <WidgetListHeader className={LIVE_COLS}>
                    <span className="eyebrow text-muted-foreground">No ar</span>
                    <span className="eyebrow whitespace-nowrap text-muted-foreground max-sm:hidden">Erros</span>
                    <span className="eyebrow text-right text-muted-foreground">30 dias</span>
                    <span />
                  </WidgetListHeader>
                  {live.map((p) => (
                    <WidgetListRow key={p.id} className={LIVE_COLS}>
                      <span className="flex min-w-0 flex-col gap-0.5">
                        <span className="truncate">{p.name}</span>
                        <span className="eyebrow text-muted-foreground">
                          {p.live!.version} · {p.live!.deployed}
                        </span>
                      </span>
                      <Sparkline
                        values={p.live!.errors}
                        color={p.live!.health === "ok" ? "var(--chart-1)" : "var(--warning)"}
                        className="h-6 w-20 max-sm:hidden"
                      />
                      <span className="text-right text-muted-foreground tabular-nums">
                        {(p.live!.uptime * 100).toLocaleString("pt-BR", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}%
                      </span>
                      <span className="flex justify-end">
                        <StatusBadge tone={HEALTH[p.live!.health].tone}>{HEALTH[p.live!.health].label}</StatusBadge>
                      </span>
                    </WidgetListRow>
                  ))}
                </WidgetList>
              </WidgetPanel>
            </Widget>

            <Widget>
              <WidgetHeader>
                <WidgetTitle>O que a Bottega fez</WidgetTitle>
              </WidgetHeader>
              <WidgetPanel className="flex flex-col pt-3">
                <WidgetList>
                  <AnimatePresence initial={false}>
                    {activity
                      .filter((a) => inScope(a.project))
                      .slice(0, 6)
                      .map((a) => (
                        <WidgetListRow key={a.id} className="grid-cols-[3rem_minmax(0,1fr)] items-baseline">
                          <span className="eyebrow text-muted-foreground tabular-nums">{a.when}</span>
                          <span className="min-w-0 text-pretty">
                            <span className="text-muted-foreground">{name(a.project)} · </span>
                            {a.text}
                          </span>
                        </WidgetListRow>
                      ))}
                  </AnimatePresence>
                </WidgetList>
              </WidgetPanel>
            </Widget>
          </div>
        </div>
      </main>

      <div className="hidden min-h-0 border-l border-border/70 lg:flex lg:flex-col">
        <Conversation state={state} flash={flash} />
      </div>

      {/* Below lg: the conversation opens as a sheet from a button. */}
      {chatOpen ? (
        <div className="fixed inset-0 z-[60] flex flex-col bg-background lg:hidden">
          <Conversation state={state} flash={flash} onClose={() => setChatOpen(false)} />
        </div>
      ) : (
        <Button
          variant="brand"
          className="fixed right-4 bottom-4 z-30 h-11 gap-2 rounded-full px-4 shadow-lg lg:hidden"
          onClick={() => setChatOpen(true)}
        >
          <MessageCircleIcon />
          Conversa
          {open.length > 0 && (
            <span className="flex size-5 items-center justify-center rounded-full bg-attention text-[11px] text-attention-foreground tabular-nums">
              {open.length}
            </span>
          )}
        </Button>
      )}
    </div>
  )
}

import * as React from "react"
import { ListChecksIcon, RotateCcwIcon, XIcon } from "lucide-react"

import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"
import { AgentOrb } from "@/components/ds/agent-orb"
import { ActionCardFields, ActionCardPanel, ResolvedRow } from "@/components/parts/action-card"
import { Confirmation } from "@/components/parts/confirmation"
import { PartTransition } from "@/components/parts/part-transition"
import { PreviewApproval, PreviewApprovalResolved } from "@/components/parts/preview-approval"
import { ChatThread, ChatThreadItem } from "@/components/chat/chat-thread"
import { ChatTurn } from "@/components/chat/chat-turn"
import { Composer, ComposerInput, ComposerSubmit, ComposerToolbar } from "@/components/chat/composer"
import type { ToolRegistry } from "@/components/chat/tool-registry"
import { PLAN, type Decision, type Project } from "@/examples/bottega/data"
import type { Outcome, useBottega } from "@/examples/bottega/use-bottega"

// The one conversation with the agent. Decisions arrive here as cards; the
// dashboard strip only points at them. Each card closes into a record once
// answered (PartTransition), and the agent answers in the thread.

export function Conversation({
  state,
  flash,
  onClose,
}: {
  state: ReturnType<typeof useBottega>
  /** Decision id to briefly highlight (opened from the dashboard strip). */
  flash: string | null
  /** Shown as a close button when the conversation is a sheet. */
  onClose?: () => void
}) {
  const { messages, decisions, projects, typing, decide, send } = state
  const [input, setInput] = React.useState("")
  const waiting = decisions.some((d) => d.state === "open")

  const tools = React.useMemo<ToolRegistry>(
    () => ({
      decision: {
        render: (part: { toolCallId: string }) => {
          const d = decisions.find((x) => x.id === part.toolCallId)
          if (!d) return null
          return (
            <div
              id={`decision-${d.id}`}
              className={cn(
                "scroll-my-24 rounded-2xl border border-transparent transition-colors duration-700",
                flash === d.id && "border-attention/50"
              )}
            >
              <PartTransition state={d.state}>
                <DecisionCard decision={d} projects={projects} onDecide={(o) => decide(d.id, o)} />
              </PartTransition>
            </div>
          )
        },
      },
    }),
    [decisions, projects, flash, decide]
  )

  return (
    <aside data-slot="bottega-conversation" className="flex min-h-0 flex-col bg-background">
      <header className="flex h-14 shrink-0 items-center gap-2.5 border-b border-border/70 px-5">
        <AgentOrb phase={typing ? "composing" : waiting ? "waiting" : "idle"} active={typing || waiting} />
        <span className="text-[15px]">Bottega</span>
        <span className="eyebrow ml-auto truncate text-muted-foreground">
          {typing ? "Escrevendo…" : waiting ? "Esperando você" : "Trabalhando em segundo plano"}
        </span>
        {onClose && (
          <Button variant="ghost" size="icon-sm" aria-label="Fechar conversa" className="-mr-2 text-muted-foreground" onClick={onClose}>
            <XIcon />
          </Button>
        )}
      </header>

      <div className="relative min-h-0 flex-1">
        <ChatThread busy={typing} className="gap-6 px-5 py-6">
          {messages.map((m, i) => (
            <ChatThreadItem key={m.id} message={m}>
              <ChatTurn
                message={m}
                tools={tools}
                phase={typing ? "composing" : "idle"}
                active={typing && i === messages.length - 1}
                actions={false}
              />
            </ChatThreadItem>
          ))}
        </ChatThread>
      </div>

      <div className="shrink-0 p-4 pt-0">
        <div className="rounded-2xl border border-border bg-card shadow-xs">
          <Composer
            onSubmit={() => {
              if (!input.trim()) return
              send(input.trim())
              setInput("")
            }}
          >
            <ComposerInput
              aria-label="Mensagem para a Bottega"
              placeholder="Converse sobre qualquer projeto…"
              value={input}
              onChange={(e) => setInput(e.target.value)}
              className="min-h-12"
            />
            <ComposerToolbar>
              <ComposerSubmit className="ml-auto" busy={false} disabled={!input.trim()} />
            </ComposerToolbar>
          </Composer>
        </div>
      </div>
    </aside>
  )
}

function DecisionCard({
  decision: d,
  projects,
  onDecide,
}: {
  decision: Decision
  projects: Project[]
  onDecide: (o: Outcome) => void
}) {
  const project = projects.find((p) => p.id === d.project)!

  if (d.kind === "recovery") {
    if (d.state !== "open")
      return (
        <ResolvedRow
          icon={<RotateCcwIcon />}
          label={project.name}
          summary={d.state === "accepted" ? "Reverter para v41 · aprovado" : "Mantida a v42"}
          muted={d.state === "declined"}
        />
      )
    return (
      <Confirmation
        title="Bottega quer reverter a migração do banco do Site"
        description="Desde a v42, 6% das requisições retornam 502. A migração mudou o índice de contatos; voltar para a v41 desfaz isso."
        status="Precisa de você"
        note="Os contatos recebidos nesse meio-tempo não se perdem."
        allowLabel="Reverter para v41"
        denyLabel="Manter v42"
        onAllow={() => onDecide({ accepted: true })}
        onDeny={() => onDecide({ accepted: false })}
      >
        <ActionCardPanel>
          <ActionCardFields
            fields={[
              { label: "Agora", value: "v42 · 6% de erro" },
              { label: "Volta para", value: "v41 · estável há 3 dias" },
              { label: "Tempo", value: "cerca de 2 minutos" },
            ]}
          />
        </ActionCardPanel>
      </Confirmation>
    )
  }

  if (d.kind === "plan") {
    if (d.state !== "open")
      return (
        <ResolvedRow
          icon={<ListChecksIcon />}
          label={project.name}
          summary={d.state === "accepted" ? "Plano aprovado · execução começou" : "Plano em ajuste"}
          muted={d.state === "declined"}
        />
      )
    return (
      <Confirmation
        title="Bottega quer começar o CRM interno com este plano"
        status="Precisa de você"
        allowLabel="Aprovar plano"
        denyLabel="Ajustar"
        onAllow={() => onDecide({ accepted: true })}
        onDeny={() => onDecide({ accepted: false })}
      >
        <ActionCardPanel>
          <ActionCardFields
            fields={[
              { label: "Escopo", value: PLAN.scope },
              { label: "Fora", value: PLAN.outOfScope },
              { label: "Prazo", value: PLAN.estimate },
              { label: "Risco", value: PLAN.risks },
            ]}
          />
        </ActionCardPanel>
      </Confirmation>
    )
  }

  if (d.state !== "open")
    return (
      <PreviewApprovalResolved
        label={project.name}
        accepted={d.state === "accepted"}
        summary={d.state === "accepted" ? "Vitrine aceita · publicando v1.8" : "Ajuste pedido"}
        note={d.note}
      />
    )
  return (
    <PreviewApproval
      title="Bottega quer publicar a nova vitrine da Loja"
      description="Busca por categoria no topo e cards maiores. Provada no preview: 6 de 6 cenários."
      before={<StorefrontBefore />}
      after={<StorefrontAfter />}
      href="#"
      note="Nada vai para produção sem o seu aceite."
      labels={{
        status: "Precisa do seu olho",
        before: "Antes",
        after: "Depois",
        open: "Abrir preview",
        accept: "Aceitar e publicar",
        requestChanges: "Pedir ajuste",
        send: "Enviar ajuste",
        cancel: "Cancelar",
        placeholder: "O que deve mudar?",
      }}
      onAccept={() => onDecide({ accepted: true })}
      onRequestChanges={(note) => onDecide({ accepted: false, note })}
    />
  )
}

/* Miniature storefronts for the preview card: drawn with tokens only. */

function StorefrontBefore() {
  return (
    <div className="flex h-full flex-col gap-1.5 p-2">
      <div className="h-1.5 w-1/3 rounded-full bg-foreground/20" />
      <div className="grid flex-1 grid-cols-3 gap-1.5">
        {Array.from({ length: 6 }, (_, i) => (
          <div key={i} className="rounded-sm bg-muted" />
        ))}
      </div>
    </div>
  )
}

function StorefrontAfter() {
  return (
    <div className="flex h-full flex-col gap-1.5 p-2">
      <div className="flex items-center gap-1">
        <div className="h-1.5 w-1/4 rounded-full bg-foreground/20" />
        <div className="ml-auto h-2.5 w-2/5 rounded-full border border-border bg-card" />
      </div>
      <div className="flex gap-1">
        {[0, 1, 2, 3].map((i) => (
          <div key={i} className={cn("h-1.5 w-6 rounded-full", i === 0 ? "bg-foreground/60" : "bg-muted")} />
        ))}
      </div>
      <div className="grid flex-1 grid-cols-2 gap-1.5">
        {Array.from({ length: 4 }, (_, i) => (
          <div key={i} className="rounded-sm bg-[color-mix(in_oklch,var(--chart-1)_14%,var(--muted))]" />
        ))}
      </div>
    </div>
  )
}

import * as React from "react"
import type { UIMessage } from "ai"

import {
  INITIAL_ACTIVITY,
  INITIAL_DECISIONS,
  INITIAL_PROJECTS,
  type Activity,
  type Decision,
  type Project,
} from "@/examples/bottega/data"

// The Bottega example's state machine. Deciding something updates the
// decision, moves the project along the flow (with the agent's work playing
// out over a couple of seconds), logs what the agent did and answers in the
// conversation. A real app replaces the timers with its backend; the shape
// of the state stays.

let seq = 0
const id = (p: string) => `${p}-${++seq}`
// Fictional morning: new entries are simply "now".
const clock = () => "agora"

function text(role: "user" | "assistant", body: string): UIMessage {
  return { id: id("m"), role, parts: [{ type: "text", text: body }] }
}

const INITIAL_MESSAGES: UIMessage[] = [
  text("user", "Bom dia! Como estão os projetos?"),
  {
    id: "m-hello",
    role: "assistant",
    parts: [
      {
        type: "text",
        text: "Bom dia! O **Blog** se recuperou sozinho de um pico de latência e o **App** segue executando. Três coisas precisam de você:",
      },
      ...INITIAL_DECISIONS.map(
        (d) =>
          ({
            type: "tool-decision",
            toolCallId: d.id,
            state: "input-available",
            input: { decision: d.id },
          }) as UIMessage["parts"][number]
      ),
    ],
  },
]

export type Outcome = { accepted: boolean; note?: string }

export function useBottega() {
  const [projects, setProjects] = React.useState<Project[]>(INITIAL_PROJECTS)
  const [decisions, setDecisions] = React.useState<Decision[]>(INITIAL_DECISIONS)
  const [activity, setActivity] = React.useState<Activity[]>(INITIAL_ACTIVITY)
  const [messages, setMessages] = React.useState<UIMessage[]>(INITIAL_MESSAGES)
  const [typing, setTyping] = React.useState(false)

  const patch = (pid: string, change: (p: Project) => Partial<Project>) =>
    setProjects((list) => list.map((p) => (p.id === pid ? { ...p, ...change(p) } : p)))
  const log = (project: string, body: string) =>
    setActivity((list) => [{ id: id("a"), project, when: clock(), text: body }, ...list])
  const later = (ms: number, fn: () => void) => window.setTimeout(fn, ms)

  function reply(body: string, delay = 700) {
    setTyping(true)
    later(delay, () => {
      setTyping(false)
      setMessages((list) => [...list, text("assistant", body)])
    })
  }

  function decide(decisionId: string, outcome: Outcome) {
    const d = decisions.find((x) => x.id === decisionId)
    if (!d || d.state !== "open") return
    setDecisions((list) =>
      list.map((x) => (x.id === decisionId ? { ...x, state: outcome.accepted ? "accepted" : "declined", note: outcome.note } : x))
    )

    if (d.kind === "recovery") {
      if (outcome.accepted) {
        patch("site", (p) => ({
          now: "Revertendo a migração…",
          stages: p.stages.map((s, i) => (i === 5 ? "active" : s)),
          live: p.live && { ...p.live, health: "recovering" },
        }))
        reply("Revertendo agora. Te aviso assim que os erros zerarem.")
        later(2600, () => {
          patch("site", (p) => ({
            now: "No ar · v41 restaurada",
            live: p.live && {
              ...p.live,
              version: "v41",
              health: "ok",
              deployed: "agora",
              errors: p.live.errors.map((_, i) => 0.3 + Math.abs(Math.sin(i * 1.3)) * 0.2),
            },
          }))
          log("site", "Reverteu a migração do banco; os erros 502 zeraram")
          reply("Pronto: o **Site** voltou para a v41 e os erros zeraram. Guardei a migração para corrigir antes de tentar de novo.", 300)
        })
      } else {
        patch("site", () => ({ now: "Investigando os 502 na v42" }))
        reply("Combinado, mantenho a v42. Sigo investigando os 502 e te chamo se piorar.")
      }
    }

    if (d.kind === "preview") {
      if (outcome.accepted) {
        patch("loja", (p) => ({ now: "Publicando v1.8…", stages: p.stages.map((s, i) => (i === 4 ? "active" : s)) }))
        reply("Aceito. Publicando a nova vitrine.")
        later(2600, () => {
          patch("loja", (p) => ({
            now: "No ar · v1.8",
            stages: p.stages.map((s, i) => (i === 4 ? "done" : i === 5 ? "active" : s)),
            live: p.live && { ...p.live, version: "v1.8", deployed: "agora" },
          }))
          log("loja", "Publicou a nova vitrine (v1.8) e começou a observar")
          reply("A **Loja v1.8** está no ar. Fico de olho nas primeiras horas.", 300)
        })
      } else {
        patch("loja", () => ({ now: "Ajustando a vitrine", stages: ["done", "done", "active", "todo", "todo", "todo"] }))
        log("loja", `Voltou à execução com o seu ajuste: “${outcome.note}”`)
        reply("Entendido, vou ajustar e te mostro um novo preview.")
      }
    }

    if (d.kind === "plan") {
      if (outcome.accepted) {
        patch("crm", () => ({ now: "Executando · 0 de 9 tarefas", stages: ["done", "done", "active", "todo", "todo", "todo"] }))
        log("crm", "Começou a execução do plano do funil")
        reply("Plano aprovado. Começando pelo modelo de dados do funil.")
      } else {
        patch("crm", () => ({ now: "Refazendo o plano com você", stages: ["done", "active", "todo", "todo", "todo", "todo"] }))
        reply("Claro. O que você quer mudar no plano?")
      }
    }
  }

  function send(body: string) {
    setMessages((list) => [...list, text("user", body)])
    reply("Anotado. Sigo com isso e te chamo quando precisar de uma decisão.", 900)
  }

  return { projects, decisions, activity, messages, typing, decide, send }
}

